package agent
import("sort";"strings";"sync";"time")
type Heartbeat struct{AgentID string `json:"agent_id"`;HostID string `json:"host_id"`;Version string `json:"version"`;Status string `json:"status"`;ObservedAt time.Time `json:"observed_at"`};type AgentState struct{AgentID string `json:"agent_id"`;HostID string `json:"host_id"`;Version string `json:"version"`;Status string `json:"status"`;LastSeen time.Time `json:"last_seen"`};type Registry struct{mu sync.RWMutex;states map[string]AgentState}
func NewRegistry()*Registry{return &Registry{states:make(map[string]AgentState)}}
func(r *Registry)Upsert(h Heartbeat)AgentState{if r==nil{return AgentState{}};h.AgentID=strings.TrimSpace(h.AgentID);h.HostID=strings.TrimSpace(h.HostID);h.Version=strings.TrimSpace(h.Version);h.Status=strings.ToLower(strings.TrimSpace(h.Status));if h.AgentID==""||h.HostID==""||len(h.AgentID)>256||len(h.HostID)>256||len(h.Version)>128||len(h.Status)>64{return AgentState{}};observed:=h.ObservedAt;if observed.IsZero(){observed=time.Now().UTC()}else{observed=observed.UTC();if observed.After(time.Now().UTC().Add(5*time.Minute)){return AgentState{}}};s:=AgentState{AgentID:h.AgentID,HostID:h.HostID,Version:h.Version,Status:h.Status,LastSeen:observed};r.mu.Lock();if r.states==nil{r.states=make(map[string]AgentState)};r.states[h.AgentID]=s;r.mu.Unlock();return s}
func(r *Registry)Get(agentID string)(AgentState,bool){if r==nil{return AgentState{},false};agentID=strings.TrimSpace(agentID);if agentID==""||len(agentID)>256{return AgentState{},false};r.mu.RLock();defer r.mu.RUnlock();s,ok:=r.states[agentID];return s,ok}
func(r *Registry)List()[]AgentState{if r==nil{return []AgentState{}};r.mu.RLock();out:=make([]AgentState,0,len(r.states));for _,s:=range r.states{out=append(out,s)};r.mu.RUnlock();sort.Slice(out,func(i,j int)bool{return out[i].AgentID<out[j].AgentID});return out}
